# ───────────────────────── 10 ─────────────────────────
CHAPTERS.append({
    "title": "المنسق التقني",
    "intro": "المنسق التقني للتكتل لا للمجموعة: يختاره رئيس تكتل حين يُشكَّل تكتله في المكتب (بعدد بحسب مجموع فئات مجموعاته)، ويوزّعه هناك على مجموعات من التكتل لا تتجاوز وحداتها حدّه (6 في الاقتصادي)، فيعمل فيها وحدها، ويقوم فيها بكل العمليات: استقبال العائلات والترحيب بها، والوثائق الصحية والملف الصحي، والتأشيرات، ووضع المجموعات والحجاج على الرحلات، والقوائم قبل المناسك، وتسجيل أداء المناسك، وقناة المجموعة، والبلاغات. في قائمته «إدارة المجموعات» و«التسجيل على الحج» و«حجاج مجموعاتي» و«التأشيرات» و«القوائم» و«الميدان». في «التسجيل على الحج» يسجّل المواطنين على الحج في مكتبه، وهذا لا يضعهم في مجموعة؛ وهي له وحده في أول الموسم. وحجاج مجموعاته يلحقهم المكتب بها بعقودهم. المثال: سامر نبيل نجار.",
    "sections": [
        {"title": "تسجيل الحجاج", "steps": [
            S("ملفي للمنسق التقني", "صفتك منسق تقني، وحالك هذا الموسم: «منسق تقني في تكتل النور — مجموعتا الخبير واللطيف».", "tech-dash", do=["اضغط «إدارة المجموعات»."], r="—"),
            S("إدارة المجموعات", "تكتلك ورئيسه، والمجموعات التي وُزّعت عليها ووحداتها، برؤسائها وحجاجها من سعتها، وعدد منسقي التكتل. ويغيّر رئيس التكتل التوزيع بنفسه، ضمن حدّك، فترى مجموعاتك الجديدة فوراً.", "tech-groups",
              do=["اضغط «حجاج مجموعاتي»."], r="—"),
            S("ابحث عن المواطن", "خمس خطوات: المواطن، الموافقة، المرافقون، الأهلية، المكتب والرسم. في الجانب «تعييني هذا الموسم» والطلبات التي سجّلتها.", "tech-reg",
              do=["اكتب الرقم الوطني للمواطن واسمه الأول كما في بطاقته الشخصية، ثم «بحث»."], r="تظهر بياناته من الشؤون المدنية.",
              note="لا يظهر شيء من بيانات المواطن حتى يطابق الاسم الأول رقمه الوطني. كل اسم لا يطابق يُسجَّل في سجل الأحداث باسمك، وبعد خمسة متتالية يتوقف البحث."),
            S("بيانات المواطن ورقم هاتفه", "تظهر بيانات المواطن من الشؤون المدنية، وليس فيها رقم هاتف: تطلبه من المواطن وتكتبه، فيصله عليه رمز الموافقة، ويُحفظ في حسابه على المنصة. إن كان له حساب في المنصة من قبل، يُرسل الرمز مباشرة إلى هاتفه المسجّل فيه ولا يُكتب رقم.", "tech-reg-found",
              do=["اختر دولة هاتف المواطن من القائمة واكتب رقمه، ثم «إرسال رمز التحقق»."], r="يصل رمز الموافقة إلى هاتف المواطن."),
            S("رمز موافقة المواطن", "اطلب منه الرمز الذي وصله. بلا الرمز لا يُفتح الطلب. «تغيير الرقم» إن أخطأت في كتابته، و«إعادة الإرسال» إن لم يصله.", "tech-reg-otp",
              do=["أدخل الرمز ثم «تأكيد الموافقة ومتابعة»."], r="تنتقل إلى المرافقين، ويُحفظ الرقم في حسابه عند تقديم الطلب."),
            S("من سيحج معه؟", "أضف المرافقين من دفتر العائلة أو بالرقم الوطني، كما في طلب الحاج.", "tech-reg-members",
              do=["أضف المرافقين ثم «افحص الأهلية»."], r="—"),
            S("الأهلية", "فحص الأهلية نفسه الذي يراه الحاج، مع الحلول المقترحة لكل ملاحظة (مثل مرافق لكبير السن).", "tech-reg-elig",
              do=["عالج الملاحظات حتى يكون الطلب مؤهلاً، ثم اختر نوع التسجيل وأكمل الدفع."], r="يُسجَّل الطلب برقم وإيصال."),
            S("تفاصيل طلب سجّلته", "لكل طلب سجّلته صفحة تفاصيل: الحساب وصاحب الطلب، الإيصالات، أفراد الطلب، المسار، وسجل الأحداث.", "tech-detail",
              do=["اضغط «طباعة» إن احتاج المواطن نسخة."], r="—"),
        ]},
        {"title": "حجاج مجموعاتي", "steps": [
            S("حجاج مجموعاتي", "في الأعلى أزرار المجموعات التي وُزّعت عليها: اضغط مجموعة لتفتحها. ترى حجاجها كما ألحقهم المكتب بعقودهم، ولكل عائلة جديدة «استلام والترحيب»، ولكل عائلة زرا «تسجيل الملف الصحي» و«الوثائق الصحية» (الشهادة الصحية والوصفات والتقارير، كما يشرحها الفصل 7)، ولكل حاج ملفه تفتحه بالضغط عليه.", "tech-requests",
              do=["اضغط «تسجيل الملف الصحي» واختر الأمراض المزمنة والاحتياجات والأدوية، ثم «حفظ وإرسال للحاج»."], r="يصل الملف إلى الحاج ليؤكده.",
              note="لا تلحق أحداً بمجموعة: الإلحاق عمل موظف المكتب حين يوقّع الحاج عقده مع المجموعة. والملف الصحي لك وحدك؛ أما استقبال العائلات والوثائق الصحية فيقوم بهما أيضاً رئيس المجموعة ومعاونه."),
            S("بقية عملياتك", "التأشيرات والميدان كما يشرحهما الفصل 7، لكل مجموعة من مجموعاتك تختارها من أزرارها في أعلى الصفحة. ووضع المجموعات على الرحلات وحافلات المناسك في «القوائم»، كما يشرحها فصلا «القوائم».", None,
              do=["افتح «التأشيرات» أو «القوائم» أو «الميدان» من القائمة الجانبية، واختر المجموعة."], r="—"),
        ]},
    ],
})

# ───────────────────────── 11 ─────────────────────────
CHAPTERS.append({
    "title": "فريق المجموعة وموجّهات التكتل",
    "intro": "المعاون والموجّه يتقدمان بصفتهما في طلب المشاركة ويؤديان الاختبار المؤتمت (أو يُعفيان عند التجديد)، ثم يحضران إلى المكتب حين تُشكَّل المجموعة التي يعملان فيها، فيُجلسهما الموظف في مقعديهما ويوقّعان عقدها. بعد ذلك يعمل المعاون مع رئيس المجموعة في عملياتها كلها، في «إدارة المجموعة» و«حجاج المجموعة» و«التأشيرات» و«الميدان» كما شرحنا في الفصل 7، ويرى «القوائم». أما الموجّه فعمله «الدروس الدينية» و«النشاطات الدينية» وحدها. والموجّهة الدينية ومعاون التكتل للتكتل كله لا لمجموعة: يختارهما رئيس التكتل حين يُشكَّل في المكتب؛ الموجّهة لدروس الحاجّات ونشاطاتهن، ومعاون التكتل يتابع العمليات للاطلاع كرئيس التكتل. الأمثلة: ياسر عبد الله (معاون) والشيخ خالد الرفاعي (موجّه ديني ب) وهالة الدقر (موجّهة دينية ب).",
    "sections": [
        {"title": "معاون المجموعة", "steps": [
            S("ملفي للمعاون", "صفتك «معاون» ومقعدك في مجموعة من التكتل، وتقييمك في الموسم السابق. بطاقة «الخطوة التالية» تقودك إلى «حجاج المجموعة».", "gdep-dash", do=["اضغط بطاقة الخطوة التالية."], r="—"),
            S("إدارة المجموعة", "مجموعتك وفريقها ورئيسها كما يراها رئيسها.", "gdep-group", do=["—"], r="—"),
            S("حجاج المجموعة", "العائلات التي ألحقها المكتب بالمجموعة، ولكل حاج ملفه تفتحه بالضغط عليه. ويستقبل المعاون العائلات ويرحّب بها، ويضيف وثائقها الصحية، كرئيس المجموعة.", "gdep-requests", do=["اضغط «استلام والترحيب» على العائلة الجديدة، أو أي حاج لترى ملفه."], r="—"),
            S("الميدان", "الميدان نفسه الذي يعمل فيه رئيس المجموعة: يسجّل المعاون فيه ما أدّته المجموعة من المناسك، وما زارته من المزارات، ومحطات سفرها. وينشر في «قناة المجموعة»، ويرفع البلاغات من «بلاغ لغرفة العمليات»، ويرسل تقريره من «يومي»: ثلاث صفحات في القائمة.", "gdep-field", do=["سجّل المنسك بعد أدائه كما في الفصل 7."], r="—"),
        ]},
        {"title": "موجّه المجموعة", "steps": [
            S("ملفي للموجّه", "صفتك موجّه ديني بدرجتك (أ، ب، ج) ومقعدك في المجموعة. في قائمتك «الدروس الدينية» و«النشاطات الدينية»، و«العقود» و«قناة التكتل».", "guide-dash", do=["افتح «الدروس الدينية» من القائمة الجانبية."], r="—"),
            S("الميدان لفريق عمليات المجموعة", "لا «ميدان» ولا «إدارة المجموعة» ولا «حجاج المجموعة» في قائمة الموجّه والموجّهة، لكن فيها «قناة المجموعة» و«بلاغ لغرفة العمليات» و«يومي». وإن فُتحت صفحة الميدان تظهر بطاقة «الميدان لفريق عمليات المجموعة»: «يعمل فيه المنسق التقني ورئيس المجموعة ومعاونه. عمل الموجّه والموجّهة في الدروس الدينية والنشاطات الدينية.»، وزر «الدروس الدينية».", "guide-field-locked",
              do=["اضغط «الدروس الدينية»."], r="تُفتح دروسك، كما يشرحها فصل «الدروس والنشاطات الدينية»."),
        ]},
        {"title": "موجّهة التكتل", "steps": [
            S("دروس الحاجّات ونشاطاتهن", "الموجّهة أو المرشدة الدينية للتكتل يوزّعها رئيسه حين يُشكَّل في المكتب على مجموعات منه لا تتجاوز وحداتها حدّها (7 في الاقتصادي). عملها فيها الدروس الدينية والنشاطات الدينية لحاجّاتها وحدهن، كما يشرحها الفصل الأخير؛ لا ميدان لها ولا «حجاج مجموعاتي». أما معاون التكتل فيرى «مجموعات التكتل» كلها، ويتابع عملياتها للاطلاع كرئيس التكتل.", None,
              do=["افتحي «الدروس الدينية» واختاري مجموعات درسك."], r="—"),
        ]},
    ],
})

# ───────────────────────── قناة التكتل ─────────────────────────
CHAPTERS.append({
    "title": "قناة التكتل",
    "intro": "لكل تكتل قناة واحدة لكادره كله: رئيسه ومحاسبه، ورؤساء مجموعاته وموجّهوها ومعاونوها، ومعاونو التكتل ومنسقوه وموجّهاته. تظهر «قناة التكتل» في القائمة الجانبية لكل من له مكان في تكتل. الجميع يقرأ، ومن يكتب يحدده رئيس التكتل بالصفة. وهي منفصلة عن «قناة المجموعة» التي يعلن فيها رئيس المجموعة لحجاجه، وعن المراسلات مع الإدارة.",
    "sections": [
        {"title": "لرئيس التكتل: إدارة القناة", "steps": [
            S("قناة التكتل", "في الوسط الرسائل بترتيب كتابتها، وفي أعلاها المثبّتة، ولكل رسالة اسم كاتبها وصفته ووقتها. وفي الجانب «من يكتب في القناة». ولا قائمة أعضاء: كل من في التكتل عضو في قناته.", "chan-head",
              do=["افتح «قناة التكتل» من القائمة الجانبية (الإطار)."], r="—"),
            S("الكتابة والرد", "اكتب رسالتك في الخانة أسفل القناة، وEnter للإرسال. «ردّ» تحت أي رسالة يضع ما تردّ عليه فوق الخانة، ويظهر في رسالتك. ولرئيس التكتل تحت كل رسالة «تثبيت» يضعها في أعلى القناة، و«حذف»، ولكل كاتب حذف رسالته. الرسالة المحذوفة تبقى في مكانها بعبارة «حُذفت هذه الرسالة» واسم من حذفها.", "chan-reply",
              do=["اكتب رسالتك ثم اضغط «إرسال» (الإطار)."], r="تظهر لكادر التكتل كله، ويصل كلاً منهم إشعار، وتُسجَّل في سجل نشاطك."),
            S("من يكتب في القناة", "اختر جاهزاً: «رئيس التكتل وحده» (الافتراضي في التكتل الجديد)، أو «القيادة ورؤساء المجموعات» (رئيس التكتل ومحاسبه ورؤساء المجموعات)، أو «كل أعضاء التكتل». أو علّم الصفات صفةً صفة. رئيس التكتل يكتب دائماً.", "chan-writers",
              do=["اختر من يكتب، ثم اضغط «حفظ»."], r="يتغير ما يراه الأعضاء فوراً: من لا يكتب تصير خانته عبارة تقول من يكتب."),
            S("إيقاف كتابة عضو", "تحت كل رسالة من غيرك زر «إيقاف كتابته»: يبقى كاتبها يقرأ القناة، ولا يكتب فيها حتى تعيدها له، مهما كانت صفته. والسبب اختياري.", "chan-mute",
              do=["اكتب السبب إن شئت، ثم اضغط «إيقاف الكتابة» (الإطار)."], r="يظهر اسمه في «موقوفون عن الكتابة» أسفل «من يكتب في القناة»، وبجانبه «إعادة الكتابة» لإرجاعها."),
        ]},
        {"title": "لكل أعضاء التكتل", "steps": [
            S("رسائل جديدة", "بجانب «قناة التكتل» في القائمة الجانبية عدد الرسائل التي لم تقرأها، ويظهر في «الإشعارات» سطر بها. وتُعدّ مقروءة حين تفتح القناة.", "chan-badge",
              do=["اضغط «قناة التكتل» (الإطار)."], r="—"),
            S("عضو يقرأ", "إن لم تكن صفتك ممن يكتبون، أو أوقف رئيس التكتل كتابتك، تقرأ كل ما يُنشر، ومكان خانة الكتابة عبارة تقول من يكتب في القناة.", "chan-member",
              do=["اطلب من رئيس التكتل إن احتجت أن تكتب."], r="—"),
        ]},
    ],
})

# ───────────────────────── 12 ─────────────────────────
CHAPTERS.append({
    "title": "القوائم: الطيران",
    "intro": "مدخل «القوائم» في القائمة الجانبية لفريق عمليات المجموعات (المنسق التقني، ورئيس المجموعة ومعاونه)، ولرئيس التكتل ومعاونه ومحاسبه، لا للموجّهين. أول تبويباته «الطيران»، ثم قوائم ما قبل المناسك (الفصل التالي). رحلات الطيران ينشئها مسؤول الطيران في إدارة الحج، ويعطي كل تكتل أيام رحلاته: رحلات ذهاب من مطار البلد (دمشق أو حلب) إلى مكة المكرمة (مطار جدة) أو المدينة المنورة، ورحلات عودة، ولكل رحلة مقاعد التكتل عليها (الرحلة كلها، أو عدد من مقاعد رحلة يتشاركها أكثر من تكتل). ثم يضع كل منسق تقني المجموعات التي وُزّع عليها على هذه الأيام: كل مجموعة كاملة بعائلاتها وفريقها، ومن يُسجَّل فيها بعد ذلك يلحق برحلتها تلقائياً. وقد يسافر حاج وحده بعيداً عن رحلة مجموعته، فيضيفه المنسق إلى رحلة أخرى من أيام التكتل. وتهبط العودة حيث يسمح مطار الذهاب: من أقلع من دمشق يعود إلى دمشق أو اللاذقية، ومن أقلع من حلب إلى حلب أو اللاذقية، ولا تقبل المنصة غير ذلك. وحين يقفل مسؤول الطيران الرحلة ويصدر كشف ركابها لا يتغير عليها شيء إلا عنده. ويرى رئيس المجموعة ومعاونه رحلتي مجموعتهما ويطبعان كشفها، ويتابع رئيس التكتل ومعاونه ومحاسبه رحلات مجموعات التكتل كلها للاطلاع. الأمثلة: سامر نبيل نجار (منسق تقني في تكتل النور)، وعبد الرحمن العلي (رئيس تكتل النور)، وأحمد سليمان الحمصي (رئيس مجموعة اللطيف).",
    "sections": [
        {"title": "المنسق التقني: أيام التكتل", "steps": [
            S("رحلات مجموعاتي", "«القوائم» في القائمة الجانبية (الإطار 1) تُفتح على تبويب «الطيران» (الإطار 2). في أعلاه بطاقة كبطاقة كل تبويب في «القوائم»: «الطيران»، ووصفه، وأيام رحلات التكتل، وزر «طباعة كشوف الرحلات»، وبجانبها ثلاثة أرقام: الحجاج والإداريون في مجموعاتك، ومن منهم على رحلة ذهاب، ومن على رحلة عودة. وتحت البطاقة سطر بعدد من بقي بلا رحلة ذهاب. وتحتها كيف تعمل الرحلات: أيام يعطيها مسؤول الطيران، ومجموعات تضعها أنت عليها، وعودة تهبط حيث يسمح مطار الذهاب.", "cfl-top",
              do=["اضغط «القوائم» في القائمة الجانبية (الإطار 1)."], r="يُفتح تبويب «الطيران».",
              note="كان «الرحلات» مدخلاً مستقلاً في القائمة الجانبية؛ صار أول تبويب في «القوائم»، ورابطه القديم يقود إليه."),
            S("أيام رحلات التكتل", "«أيام رحلات التكتل» قسمان: الذهاب، ثم العودة، وبجانب عنوان كل قسم أيامه. لكل رحلة بطاقة: تاريخها بالهجري والميلادي، ورقمها وناقلها، ومسارها (مثل «دمشق ← جدة (مكة المكرمة)» أو «المدينة المنورة ← اللاذقية»)، وساعتا الإقلاع والهبوط، وحالتها. وتحتها «مقاعد تكتلك» بما أُسند منها، و«الرحلة كلها لتكتلك» أو «مقاعدك من رحلة مشتركة»، ثم المجموعات عليها بعدد مسافري كل منها. وفي بطاقة العودة لمن تصلح: «لمن أقلع من دمشق أو حلب».", "cfl-days",
              do=["راجع أيام التكتل ومقاعده على كل رحلة."], r="—",
              note="مقاعد التكتل على الرحلة يتشاركها منسقوه كلهم: ما يُسنده منسق ينقص مما يبقى لغيره. في تكتل النور: ذهاب RB 507 (24 ذو القعدة) وRB 515 إلى المدينة المنورة، وعودة RB 508 وRB 538 إلى اللاذقية (60 مقعداً من رحلة يتشاركها ثلاثة تكتلات) وRB 516 من جدة. إن لم يُعطَ التكتل أياماً بعد تظهر رسالة بذلك."),
            S("طباعة كشوف الرحلات", "زر «طباعة كشوف الرحلات» في بطاقة التبويب يطبع كل الرحلات على ورق A4، وفي أعلى كل بطاقة رحلة رمز الطابعة «طباعة كشف <رقم الرحلة>» يطبعها وحدها. والكشف بشكل كل ما تطبعه المنصة، بخطها: في أعلاه ترويسة الجمهورية العربية السورية ووزارة الأوقاف وإدارة الحج والعمرة بالعربية والإنجليزية وشعار الإدارة، ثم العنوان والتكتل ووقت الطباعة، ثم مربعات بعدد الرحلات والمسافرين والمجموعات. ثم كل رحلة في صفحة: رقمها واتجاهها ومسارها، ومربعات بيومها وساعتي الإقلاع والوصول وناقلها وعدد مسافريها، ثم جدول بعنوان أخضر بمسافريها من مجموعاتك: الرقم، والاسم، والصفة (حاج أو إداري)، والمجموعة، والمقعد، وما يحتاجه، وعمود «صعد ✓» للتأشير عند البوابة.", None,
              do=["اضغط «طباعة كشوف الرحلات»، أو رمز الطابعة على رحلة واحدة.", "اختر الطابعة في نافذة المتصفح."], r="يُطبع الكشف وحده دون القائمة الجانبية وأزرار الصفحة. ولرئيس التكتل ومعاونه ومحاسبه الطباعة نفسها للاطلاع."),
        ]},
        {"title": "المنسق التقني: وضع المجموعات والحجاج", "steps": [
            S("إضافة مسافرين: مجموعة كاملة", "في كل بطاقة رحلة زر واحد: «إضافة مسافرين». يفتح نافذة مجموعاتك وفي أعلاها تبويبات، على كل تبويب كم اخترت من أفرادها (الإطار 1). تختار المجموعة، ثم «الكل في <المجموعة>» (الإطار 2) فتتعلّم عائلاتها وفريقها كلهم تحته، ثم تزيل من لا يسافر. فإن اخترت كل من لا رحلة له منها في هذا الاتجاه أُسندت المجموعة كاملةً، ومن ينضم إليها لاحقاً يلحق برحلتها. ويُعطَّل من على هذه الرحلة أو من لا تصلح له، مع سببه، وتقول النافذة تحت التبويبات إن كانت المجموعة كلها لا تصلح. وفي نافذة رحلة الذهاب «وعودة المجموعات المسندة كاملة» (الإطار 3): رحلات العودة من أيام التكتل التي يسمح بها مطار هذا الذهاب، والمقابلة مختارة سلفاً. وفي الأسفل «اخترت N من M مقعداً باقية».", "cfl-assign",
              do=["اضغط «إضافة مسافرين» في بطاقة الرحلة.", "اختر المجموعة من التبويبات، ثم «الكل في <المجموعة>»، وأزل من لا يسافر.", "اترك العودة المقترحة أو غيّرها، ثم اضغط «إضافة إلى الرحلة»."], r="تظهر رسالة «أُضيف N مسافراً» وفيها «مجموعة اللطيف كاملة وعودتها»، وتظهر المجموعة في بطاقتي الرحلتين.",
              warn="لا يُفعَّل «إضافة إلى الرحلة» إن زاد المختارون على المقاعد الباقية للتكتل على الرحلة. ولا يُسند إلى رحلة ليست من أيام التكتل."),
            S("إضافة مسافرين: فرادى", "لمن يسافر وحده بعيداً عن رحلة مجموعته، وهي حالات قليلة: في النافذة نفسها تختار المجموعة، ثم تعلّم من يسافر وحده دون «الكل» (الإطار 1). أمام كل فرد حاله: «بلا رحلة عودة»، أو «يُنقل من RB 508» إن كان على رحلة أخرى في هذا الاتجاه. ويُعطَّل من لا تصلح له الرحلة، مع سببه، ومن رحلته مقفلة. ويمكن أن تجمع في الخطوة نفسها مجموعة كاملة وأفراداً من غيرها.", "cfl-pilgrims",
              do=["اضغط «إضافة مسافرين» في بطاقة الرحلة.", "اختر المجموعة، ثم علّم الحاج أو أكثر.", "اضغط «إضافة إلى الرحلة» (الإطار 2)."], r="يُضاف إلى الرحلة فرداً، ويُنقل من رحلته السابقة إن كانت له."),
            S("فرادى على الرحلة", "في بطاقة الرحلة تحت مجموعاتها «فرادى خارج رحلة مجموعتهم» بأسمائهم ومجموعاتهم. وبجانب كل مجموعة وكل فرد زر الإزالة ما دامت الرحلة مفتوحة: تُزال المجموعة كاملة، أو الفرد وحده، فيصير بلا رحلة في هذا الاتجاه حتى تضعه على غيرها.", "cfl-apart",
              do=["—"], r="—",
              note="حين يقفل مسؤول الطيران الرحلة يظهر في بطاقتها «مقفلة: صدر كشف ركابها، وأي تغيير عليها عند مسؤول الطيران»، وتختفي أزرار الإسناد والإزالة."),
            S("مجموعاتي ورحلاتها", "لكل مجموعة: عدد أفرادها (العائلات وفريق المجموعة)، ورحلة الذهاب ورحلة العودة بالرقم والتاريخ والساعة والمسار. «لم تُسند بعد» يعني أن المجموعة لم توضع على رحلة في هذا الاتجاه، و«x/y على رحلة» أن بعض أفرادها على رحلات أخرى فرادى. القفل بجانب رقم الرحلة يعني أنها أُقفلت وصدر كشف ركابها.", "cfl-table",
              do=["راجع المجموعات التي لم تُسند بعد، وضعها على أيام التكتل."], r="—",
              tip="إن وضع مسؤول الطيران أحداً من مجموعاتك على رحلة خارج أيام التكتل (كمن تخلّف عن رحلته)، تظهر في آخر الصفحة «رحلات أخرى عليها من تكتلك»."),
        ]},
        {"title": "رئيس التكتل ومعاونه ومحاسبه", "steps": [
            S("رحلات التكتل للاطلاع", "في تبويب «الطيران» لرئيس التكتل «رحلات <التكتل>»: الأرقام نفسها لمجموعات التكتل كلها، ثم سطر «رئيس التكتل: للاطلاع فقط. يتابع إسناد المجموعات إلى الرحلات ولا يشارك فيها؛ يقوم بها المنسق التقني في مجموعاته.»، ثم أيام رحلات التكتل بمجموعات كل رحلة، و«مجموعات تكتلي ورحلاتها»، دون «إسناد مجموعات» ولا «إضافة حجاج» ولا أزرار الإزالة.", "cfl-viewonly",
              do=["تابع المجموعات التي لم تُسند بعد مع منسقيها."], r="—"),
        ]},
        {"title": "رئيس المجموعة ومعاونه", "steps": [
            S("رحلات المجموعة", "رئيس المجموعة ومعاونه يريان في تبويب «الطيران» رحلة ذهاب المجموعة ورحلة عودتها: الرقم والناقل والمسار والموعد والتجمّع والحالة.", "gfl-top",
              do=["اضغط «القوائم» في القائمة الجانبية."], r="ترى رحلتي مجموعتك.",
              note="إن لم توضع مجموعتك على رحلة بعد تظهر رسالة بذلك. يضعها منسقها التقني على أحد أيام رحلات التكتل."),
            S("كشف المجموعة", "جدول بكل عائلة في المجموعة وأفرادها، ثم فريق المجموعة: رحلة الذهاب ورحلة العودة لكل فرد بمسارها، وحالة إسناده (مسند، مثبت، صعد)، وحالته الإجمالية، واحتياجاته الخاصة. ومن أضافه المنسق إلى رحلة أخرى يظهر في سطره برحلته.", "gfl-list",
              do=["اضغط «طباعة الكشف» وخذه معك إلى المطار."], r="يُطبع كشف المجموعة وحده على ورق A4: عائلة عائلة، ولكل فرد رحلة ذهابه ورحلة عودته، وعمود «صعد ✓» للتأشير عند البوابة.",
              tip="العائلة التي يلحقها المكتب بالمجموعة بعد وضعها على الرحلة تظهر في الكشف على الرحلة نفسها دون أي إجراء."),
        ]},
    ],
})

# ───────────────────────── القوائم: حافلات المناسك ─────────────────────────
CHAPTERS.append({
    "title": "القوائم: حافلات المناسك والروضة الشريفة",
    "intro": "بعد «الطيران» في «القوائم» خمسة تبويبات، قائمة لكل تنقّل في الموسم: التروية (من الفندق في مكة إلى مخيم المجموعة في منى)، وعرفة (من منى إلى عرفات ثم إلى مزدلفة)، ومنى أيام التشريق، والذهاب إلى المدينة المنورة، وحجز الروضة الشريفة. لكل قائمة يسند فريق المواصلات في إدارة الحج والعمرة إلى التكتل حافلاته: اسمها وموعدها ولوحتها وسائقها ومقاعدها. ويضع المنسق التقني عليها حجاج مجموعاته وإدارييها، كما يضع المجموعات على الرحلات. أما الروضة الشريفة فلا حافلات لها: قائمتان، للرجال وللنساء. ويرى رئيس المجموعة ومعاونه قوائم مجموعتهما، ويتابع رئيس التكتل ومعاونه ومحاسبه قوائم التكتل كله، ولا يضع أحد منهم أحداً على حافلة. ويرى الحاج حافلة كل فرد من عائلته في بوابته («الطيران والمشاعر» ← «قوائمي»).",
    "sections": [
        {"title": "المنسق التقني: قائمة وحافلاتها", "steps": [
            S("قائمة وحافلاتها", "اضغط تبويب القائمة، مثل «التروية» (الإطار 1). بطاقة القائمة: اسمها ووصفها وموعدها، وزر «طباعة قائمة <القائمة>» (الإطار 2)، وثلاثة أرقام: «في مجموعاتك» و«على القائمة» و«مقاعد N حافلات»، وتحتها بالأحمر كم من مجموعاتك «لم يوضعوا على هذه القائمة بعد». ثم بطاقة لكل حافلة أسندها فريق المواصلات إلى التكتل: اسمها، وموعدها، و«اللوحة» و«السائق»، ومقاعدها المشغولة من كلها بشريط، ومن عليها من حجاج وإداريين، لكلٍّ صفته ومجموعته.", "lists-page",
              do=["اختر القائمة من تبويباتها."], r="تظهر حافلات التكتل في هذه القائمة."),
            S("أضف إلى الحافلة", "في أسفل كل حافلة زر «أضف إلى <الحافلة>»، يفتح النافذة نفسها التي في الطيران: مجموعاتك تبويبات في أعلاها (الإطار 1)، تختار المجموعة ثم «الكل في <المجموعة>» (الإطار 2) فتتعلّم كلها تحته، إداريوها ثم حجاجها، ثم تزيل من لا يذهب. ومعها «ابحث بالاسم». لا يظهر فيها إلا من لم يوضع على هذه القائمة بعد، وتبقى اختياراتك وأنت تنتقل بين المجموعات. وفي أسفلها «اخترت N من M مقعداً باقية»، بالأحمر إن زدت.", "lists-add",
              do=["اضغط «أضف إلى <الحافلة>».", "اختر المجموعة، ثم «الكل في <المجموعة>»، وأزل من لا يذهب.", "اضغط «أضف إلى <الحافلة>» في أسفل النافذة."], r="تظهر رسالة «أُضيف … إلى <الحافلة>»، ويُضاف المختارون إلى الحافلة بقدر مقاعدها الباقية.",
              note="حين تمتلئ الحافلة يصير مكان الزر «اكتملت مقاعدها»، وحين يكون كل من في مجموعاتك على القائمة «كل من في مجموعاتك على هذه القائمة». وفي الروضة الشريفة لا حد للمقاعد."),
            S("الحافلة وركابها", "تتحدث بطاقة الحافلة: عدد ركابها من مقاعدها، وأسماؤهم، و«عرض الكل» إن زادوا على ثمانية. وبجانب كل اسم من مجموعاتك زر × يزيله عنها، فيعود إلى من لم يوضعوا بعد. وفي أعلى البطاقة رمز الطابعة «طباعة <الحافلة>» (الإطار) يطبعها وحدها.", "lists-bus",
              do=["اضغط × لإزالة من وُضع خطأً.", "اضغط رمز الطابعة لتطبع كشف الحافلة."], r="—"),
            S("طباعة القائمة", "«طباعة قائمة <القائمة>» يطبع القائمة كلها على ورق A4، ورمز الطابعة على حافلة يطبعها وحدها. والورقة بشكل كل ما تطبعه المنصة، بخطها: ترويسة الجمهورية العربية السورية ووزارة الأوقاف وإدارة الحج والعمرة بالعربية والإنجليزية وشعار الإدارة، ثم عنوان القائمة (واسم الحافلة إن طُبعت وحدها) والتكتل ووقت الطباعة، ومربعات بالموعد وعدد الحافلات والركاب والمقاعد. ثم كل حافلة في صفحة: اسمها، ومربعات بموعدها ولوحتها وسائقها وهاتفه وركابها من مقاعدها، وجدول بعنوان أخضر: #، الاسم، الصفة، المجموعة، ومربع «صعد» يعلّمه المنسق عند الصعود.", None,
              do=["اطبع كشف كل حافلة وخذه معك يوم المنسك."], r="—"),
            S("طلب حافلة إضافية", "إن لم تتسع حافلات التكتل في القائمة لحجاج مجموعاتك تظهر فوقها بطاقة «لا تتسع حافلات التكتل في هذه القائمة لـ N من مجموعاتك.» وزر «طلب حافلة إضافية»: خانة «بلا مقعد» (فيها العدد سلفاً)، و«ملاحظة للمواصلات» (مثل: بينهم ستة على كراسٍ متحركة)، ثم «إرسال الطلب».", None,
              do=["اضغط «طلب حافلة إضافية»، وراجع العدد واكتب ملاحظتك، ثم «إرسال الطلب»."], r="يصل الطلب إلى فريق المواصلات، ويظهر في البطاقة بحاله: «عند فريق المواصلات»، ثم «أُسندت حافلة N» وتظهر الحافلة الجديدة في القائمة، أو «رُفض» مع السبب."),
        ]},
        {"title": "الروضة الشريفة", "steps": [
            S("قائمتا الروضة الشريفة", "تبويب «حجز الروضة الشريفة» بلا حافلات: قائمتان، «الروضة الشريفة — الرجال» و«الروضة الشريفة — النساء»، بلا حد للمقاعد ولا شيء يسنده فريق المواصلات. وفي بطاقة القائمة «الرجال · النساء» بعدد من على كلٍّ منهما. و«أضف إلى الروضة الشريفة — الرجال…» لا يعرض إلا الرجال، و«— النساء» لا يعرض إلا النساء. وفي الطباعة عمود «حضر ✓» بدل «صعد ✓».", "lists-rawdah",
              do=["أضف إلى كل قائمة من سيذهب إلى الروضة من رجال مجموعاتك ونسائها."], r="يرى الحاج في بوابته أنه على قائمة الرجال أو النساء."),
        ]},
        {"title": "من يرى القوائم", "steps": [
            S("رئيس التكتل ومعاونه ومحاسبه", "يرون قوائم مجموعات التكتل كلها وحافلاتها، وفي أعلاها «رئيس التكتل: للاطلاع فقط. يتابع القوائم والحافلات ولا يشارك فيها؛ يقوم بها المنسق التقني في مجموعاته.». الأرقام لـ«في التكتل»، ولا «أضف إلى» ولا ×، ويطبعون القائمة أو أي حافلة منها.", "lists-viewonly",
              do=["اطبع ما تحتاجه من القوائم."], r="—"),
            S("رئيس المجموعة ومعاونه", "يريان قوائم مجموعتهما، وفوقها سطر «قوائم <المجموعة> كما أعدّها المنسق التقني. يضع الحجاج والإداريين على الحافلات هو وحده.»، ويطبعانها.", None,
              do=["راجع مع منسق مجموعتك من بقي بلا حافلة."], r="—"),
        ]},
    ],
})

# ───────────────────────── الدروس والنشاطات الدينية ─────────────────────────
CHAPTERS.append({
    "title": "الدروس والنشاطات الدينية",
    "intro": "صفحتان في القائمة الجانبية لموجّه المجموعة (من يشغل مقعد الموجّه فيها) ولموجّهة التكتل (لحاجّات المجموعات التي وُزّعت عليها)، ويراهما للمتابعة دون تعديل كل من له مكان في التكتل: رئيس المجموعة ومعاونه، والمنسق التقني، ورئيس التكتل ومعاونه ومحاسبه. فالموجّه والموجّهة وحدهما يعطيان الدروس ويتابعان النشاطات، وهما عملهما في الموسم: لا ميدان لهما. «الدروس الدينية»: دروس بموعد ومكان، يرى الحجاج المدعوون كل درس في بوابتهم ويقولون من سيحضر من عائلاتهم، ويسجّل الموجّه من حضر الدرس. «النشاطات الدينية»: حلقات تُتابَع حاجاً حاجاً: تحفيظ القرآن (أي صفحة وأي سورة وأي جزء)، وتحفيظ الحديث (أي حديث من الأربعين النووية)، وحفظ أدعية الحج والعمرة، والختمة الجماعية (من قرأ أي جزء). يدرّس الموجّه رجال المجموعة أو المجموعة كلها، والموجّهة النساء وحدهن، فلا يظهر درسها ولا نشاطها إلا للحاجّات. الأمثلة: الشيخ خالد الرفاعي (موجّه مجموعة اللطيف) وهالة الدقر (موجّهة تكتل النور).",
    "sections": [
        {"title": "الدروس الدينية", "steps": [
            S("دروسي", "مدخل «الدروس الدينية» في القائمة الجانبية (الإطار 1). في أعلاه أربعة أرقام: الدروس القادمة، والتي أُعطيت، ومتوسط الحضور، ومن قالوا إنهم سيحضرون القادمة. ثم «القادمة» و«المنتهية» و«الملغاة»، وزر «درس جديد» (الإطار 2). لكل درس بطاقة: لمن هو (للجميع، للرجال، للنساء) ومرحلته (قبل السفر، في مكة، في المشاعر، في المدينة) وحاله، وعنوانه وموضوعه، وموعده بالميلادي والهجري ومدته ومكانه، ومجموعاته ومن يعطيه، وكلمته للحجاج، والمدعوون ومن قالوا سيحضرون.", "lessons-guide",
              do=["اضغط «الدروس الدينية» في القائمة الجانبية."], r="—"),
            S("درس جديد", "نافذة «درس جديد»: عنوان الدرس، والموضوع (أحكام الإحرام، العمرة، يوم التروية وعرفة، الرمي، الإفاضة والوداع، أحكام المرأة، زيارة المسجد النبوي، السيرة، الأدعية…)، والمرحلة، والتاريخ والساعة والمدة، والمكان، و«لمن الدرس»: للموجّه «للرجال» أو «للجميع»، وللموجّهة «للنساء» وحده. ومن يعمل في أكثر من مجموعة يختار مجموعات الدرس. وفي الأسفل كلمة اختيارية للحجاج: ما يحضرونه أو ما يقرؤونه قبله.", "lessons-new",
              do=["املأ الحقول، واختر لمن الدرس (الإطار 1).", "اضغط «إضافة الدرس» (الإطار 2)."], r="تظهر رسالة «أُضيف الدرس»، ويراه المدعوون في بوابتهم فوراً."),
            S("تسجيل الحضور", "«تسجيل الحضور» على بطاقة الدرس يفتح قائمة المدعوين وحدهم (في درس للنساء الحاجّات وحدهن): لكل حاج عمره وغرفته واحتياجاته، وشارة «قال سيحضر» لمن أكّد من بوابته. فوقها المدعوون ومن حضر ومن لم يحضر، والبحث بالاسم أو الغرفة، و«الكل حاضر». يُحفظ كل تحديد فوراً، فتستطيع الإغلاق والعودة.", "lessons-roll",
              do=["حدّد كل من حضر، أو اضغط «الكل حاضر» ثم ألغِ من لم يحضر.", "اضغط «إنهاء الدرس وحفظ الحضور» (الإطار)."], r="تظهر رسالة «سُجّل حضور الدرس» بعدد من حضر، ويرى كل حاج حضوره في بوابته.",
              tip="فتحت الحضور خطأً؟ «تراجع عن فتح الحضور» يعيد الدرس قادماً كما كان. ولإلغاء درس اضغط «إلغاء الدرس» واكتب السبب: يراه المدعوون في بوابتهم."),
            S("الدروس المنتهية", "في «المنتهية» كل درس سُجّل حضوره: «حضر 41 من 46 (89%)»، وزر «الحضور» يفتح قائمته للاطلاع.", "lessons-done",
              do=["—"], r="—"),
            S("دروس الموجّهة للحاجّات", "لموجّهة التكتل «لمن الدرس» خيار واحد: «للنساء»، وتحته أن الدرس لا يظهر إلا للحاجّات. وتختار مجموعات درسها من المجموعات التي وُزّعت عليها، فيُدعى إليه نساؤها كلهن.", "lessons-female",
              do=["اختاري مجموعات الدرس، ثم «إضافة الدرس»."], r="—"),
            S("يتابعها فريق المجموعة والتكتل", "رئيس المجموعة ومعاونه، والمنسق التقني، ورئيس التكتل ومعاونه ومحاسبه يرون دروس مجموعاتهم كلها ونشاطاتها، من الموجّه والموجّهة، بحضورها، دون «درس جديد» ولا تسجيل حضور: على كل درس «يسجّل حضوره» باسم من يعطيه.", "lessons-head",
              do=["—"], r="—"),
        ]},
        {"title": "النشاطات الدينية", "steps": [
            S("نشاطاتي", "مدخل «النشاطات الدينية» في القائمة الجانبية (الإطار 1). في أعلاه: عدد النشاطات، والحجاج المشاركون، والتسميعات المسجّلة، ومتوسط الإنجاز. ثم بطاقة لكل نشاط: نوعه ولمن هو، واسمه وما يغطيه (مثل «جزء عمّ (الجزء 30)، من السور القصيرة»)، وموعد حلقاته ومكانها، ومتوسط إنجاز مشاركيه بشريط (وفي الختمة «قُرئ 18 من 30 جزءاً»)، وعدد المشاركين من المدعوين، وزر «المتابعة».", "act-list",
              do=["اضغط «المتابعة» على النشاط."], r="تفتح متابعة النشاط."),
            S("نشاط جديد", "«نشاط جديد» (الإطار 2) يفتح نافذة بأربعة أنواع: «تحفيظ القرآن» (من الجزء… إلى الجزء…، ومن آخر الجزء: السور القصيرة أولاً كما يُحفظ جزء عمّ)، و«تحفيظ الحديث» (من الحديث… إلى الحديث… من الأربعين النووية، بأوائلها)، و«حفظ أدعية الحج والعمرة» (عشرة أدعية بترتيب الحاجة إليها: دعاء السفر، والتلبية، ودخول المسجد، وبين الركنين، والصفا والمروة، ويوم عرفة، والتكبير، وزمزم، والسلام على النبي ﷺ، وأذكار الصباح والمساء)، و«ختمة جماعية» (الأجزاء الثلاثون). وتحت النوع ما يغطيه وعدد صفحاته، ثم موعد الحلقات وتاريخ البدء والمكان ولمن النشاط.", "act-new",
              do=["اختر النوع وما يغطيه، واملأ الموعد والمكان.", "اضغط «بدء النشاط»."], r="تظهر رسالة «بدأ النشاط»، ويراه المدعوون في بوابتهم فينضمون إليه."),
            S("متابعة النشاط", "جدول المشاركين: لكل حاج إنجازه (مثل «16/23» بشريط)، وآخر تسميع («صفحة 589 — الانشقاق — الجزء 30» وتقديره وتاريخه)، والتالي («صفحة 588 — المطففين — الجزء 30»)، أو «أتمّ الحفظ». وفي الحديث: «الحديث 7: الدين النصيحة». و«إضافة مشاركين» تعرض المدعوين الذين لم ينضموا بعد، تختار منهم من تضيفه.", "act-tracker",
              do=["اضغط «تسميع» أمام الحاج."], r="يُفتح تسجيل التسميع تحت الجدول."),
            S("تسجيل التسميع", "في تحفيظ القرآن «من» و«إلى»: صفحات النشاط بسورها وأجزائها، وعلى ما حفظه علامة ✓، والتالي مختار سلفاً. وفي الحديث والأدعية تختار ما سمّعه من قائمته. ثم التقدير: ممتاز، جيد جداً، جيد، يحتاج مراجعة، وملاحظة اختيارية.", "act-record",
              do=["اختر ما سمّعه والتقدير (الإطار).", "اضغط «حفظ»."], r="تظهر رسالة «سُجّل التسميع»، ويتقدم إنجاز الحاج في الجدول وفي بوابته."),
            S("الختمة الجماعية", "في الختمة شبكة الأجزاء الثلاثين: الجزء المقروء أخضر وعليه اسم قارئه، والباقي رمادي. وأمام كل مشاركة «قرأ» تختار له الأجزاء التي قرأها، فيصير الجزء مقروءاً.", "act-khatma",
              do=["اضغط «قرأ» واختر الأجزاء، ثم «حفظ»."], r="—"),
        ]},
    ],
})

FAQ = [
    ("من يكتب في «قناة التكتل»؟", "يقرؤها كادر التكتل كله، ويكتب فيها من يحدده رئيس التكتل بالصفة: هو وحده افتراضياً، أو القيادة ورؤساء المجموعات، أو الجميع. ويستطيع إيقاف كتابة عضو بعينه، وتثبيت رسالة، وحذف أي رسالة."),
    ("على كم مجموعة يُوزَّع المنسق أو الموجّهة؟", "على ما تتسع له وحداته: لكل مجموعة وحدات بقدر فئتها (الأولى 1 … الرابعة 4)، ولكل منسق حدّ (6 في الاقتصادي) ولكل موجّهة أو مرشدة حدّ (7). يوزّعهم رئيس التكتل على المجموعات حين يُشكَّل التكتل في المكتب، فلا يتجاوز أحد حدّه، ولا يُنشأ التكتل إن تجاوزه أحد. ولهذا لا يقلّ عددهم في التكتل عمّا يتسع لكل مجموعاته."),
    ("هل تدخل مجموعة تكتلاً حجاجها أكثر من سعة فئتها في مستواه؟", "لا. سعة المجموعة بفئتها في مستوى التكتل (في خمس نجوم أقل من الاقتصادي). إن كان فيها حجاج أكثر من سعتها في هذا المستوى يظهر ذلك في شروط التكتل عند الموظف، ولا يُنشأ تكتل فيه مجموعة كذلك."),
    ("من يرى حجاج المجموعة وملفاتهم؟", "يعمل عليهم فريق عمليات المجموعة: منسقها التقني، ورئيسها، ومعاونه، فيرون كل حجاجها بأسمائهم ويفتحون ملف أي حاج بالضغط عليه. ويتابعهم للاطلاع رئيس التكتل ومعاونه ومحاسبه من «إدارة التكتل». أما الموجّه والموجّهة فيرون في الدروس والنشاطات الدينية من يُدعى إليها. ولا يرى أحد حجاج مجموعة ليست من تكتله."),
    ("من يحدد رحلة مجموعتي؟", "منسقها التقني، على الأيام التي أعطاها مسؤول الطيران للتكتل. يعطي المسؤول كل تكتل رحلاته ذهاباً وعودة ومقاعده عليها، ويضع كل منسق مجموعاته كاملة على رحلاتها من «القوائم» ← «الطيران». ويتابع رئيس التكتل ذلك للاطلاع."),
    ("هل يمكن أن يسافر حاج وحده على رحلة غير رحلة مجموعته؟", "نعم، في حالات قليلة: يضيفه منسق مجموعته التقني من «إضافة مسافرين» في بطاقة رحلة أخرى من أيام تكتله، فيعلّمه وحده دون «الكل»، فيُنقل من رحلة مجموعته في هذا الاتجاه. وتبقى رحلته الأخرى كما هي."),
    ("إلى أين تعود رحلة الحاج؟", "إلى ما يسمح به مطار ذهابه: من أقلع من دمشق يعود إلى دمشق أو اللاذقية، ومن أقلع من حلب إلى حلب أو اللاذقية. وتقلع العودة من جدة أو المدينة المنورة بعد وصول الذهاب. لا تقبل المنصة رحلة عودة غير ذلك، لا للمنسق التقني ولا لمسؤول الطيران."),
    ("هل أستطيع تغيير رحلة بعد إقفالها؟", "لا. حين يقفل مسؤول الطيران الرحلة يصدر كشف ركابها إلى نسك مسار والناقل، وأي تغيير عليها بعد ذلك عنده وحده، بسبب مكتوب وكشف بإصدار جديد."),
    ("ألحق المكتب عائلة جديدة بمجموعتي بعد وضعها على الرحلة، هل تسافر معنا؟", "نعم. كل من يُلحق بالمجموعة يلحق برحلتها تلقائياً، ما دامت فيها مقاعد ولم تُقفل. وإلا يضعه المنسق التقني على رحلة أخرى من أيام التكتل، أو يعالجه مسؤول الطيران."),
    ("من يضيف تأشيرة الحاج؟", "المنسق التقني للمجموعة وحده. تصدر التأشيرة من وزارة الخارجية السعودية وتصل بالبريد إلى المجموعة، فيضيفها المنسق إلى الحاج من «التأشيرات»: ملفها ورقمها. وحين تكتمل تأشيرات العائلة تصدر خطوتها في بوابتها وتُفتح رحلتها. ويراها رئيس المجموعة ومعاونه، ورئيس التكتل ومعاونه ومحاسبه، للاطلاع."),
    ("من يرى درس الموجّهة؟", "حاجّات المجموعات التي اختارتها وحدهن: دروس الموجّهة ونشاطاتها للنساء فقط. ودرس الموجّه لرجال المجموعة أو للمجموعة كلها، كما يختار."),
    ("كيف أعرف أين وصل الحاج في الحفظ؟", "من «النشاطات الدينية» ← «المتابعة»: لكل حاج آخر ما سمّعه (الصفحة وسورتها وجزؤها، أو الحديث، أو الدعاء) وتقديره، والتالي. ويرى الحاج الشيء نفسه في بوابته."),
    ("هل يمكنني أن أكون حاجاً وإدارياً في الموسم نفسه؟", "لا. حسابك واحد، وفي كل موسم تختار به مساراً واحداً: الحج أو صفة إدارية. وفي موسم آخر تستطيع أن تختار غير ما اخترته، ويبقى ملفك الإداري وسجلّك كما هما."),
    ("كنت حاجاً في موسم سابق، كيف أتقدّم لصفة إدارية؟", "ادخل بحسابك نفسه، ومن «ملفي» اختر «أفتح ملفاً إدارياً جديداً» في بطاقة الموسم، أو ادخل من باب الإداريين فيأخذك إلى السؤال نفسه. يُفتح لك ملف إداري وتتقدّم لصفة من «التسجيل كإداري»."),
    ("هل الأكاديمية للحجاج فقط؟", "لا. الأكاديمية لكل من له حساب في المنصة. تجدها في آخر القائمة الجانبية لبوابة الإداريين، وتقدّمك فيها لحسابك، يبقى من موسم إلى موسم."),
    ("هل أتقدم بأكثر من صفة؟", "لا. صفة واحدة في الموسم. يمكنك الاستمرار في صفتك السابقة أو التقدم لصفة أخرى تفتحها وثائقك."),
    ("لماذا تظهر صفة مقفلة؟", "لأن ملفك يخلو مما تطلبه (وثيقة أو شهادة أو مهارة)، أو لأن عمرك أو جنسك أو خبرتك لا تناسبها بحسب جدول الإدارة. يظهر تحت البطاقة ما ينقصك وأين تضيفه."),
    ("ما الفرق بين «مطلوبة» و«تقوّي الطلب»؟", "المطلوبة لا يُقدَّم الطلب دونها. التي تقوّي الطلب تظهر في طلبك إن كانت في ملفك، ولا تمنع التقديم إن لم تكن."),
    ("متى أدفع رسم التسجيل؟", "بعد ثبوت أهليتك للصفة التي اخترتها فقط. التحقق من الأهلية يسبق الدفع، فلا تدفع رسماً عن صفة لا تستوفي شروطها."),
    ("متى أُعفى من الاختبار؟", "عند الاستمرار في الصفة نفسها إذا بلغ تقييمك في آخر موسم الحد الذي تحدده الإدارة ولم تنقطع أكثر من موسم."),
    ("وثيقتي منتهية الصلاحية، ماذا أفعل؟", "اضغط «حدّثها الآن» وارفع نسخة صادرة هذا الموسم. مدة صلاحية كل وثيقة تحددها الإدارة."),
    ("هل اختباري مثل اختبار الصفات الأخرى؟", "لا. لكل صفة اختبارها بأقسامه، تُسحب أسئلته من بنك أسئلتها، وتشترك الصفات في أسئلة قليلة مثل الإسعافات الأولية والطوارئ والتعامل مع الحجاج. وتحدد الإدارة أي سؤال يدخل اختبار أي صفة."),
    ("هل أستطيع أداء الاختبار من البيت؟", "لا. الاختبار في قاعة المركز الامتحاني لمحافظة قيدك: يفتحها المشرف ويسجّل حضورك ببطاقتك، ثم يوافق على دخولك من جهازك بعد أن يطابق رمز الاقتران."),
    ("وصلت إلى القاعة بعد بدء الاختبار", "يسجّل المشرف حضورك ويوافق على دخولك فتدخل، ويبدأ وقتك من لحظة دخولك. وبعد أن ينهي المشرف الجلسة لا يدخلها أحد، ومن لم يحضر يُسجَّل غائباً، ويؤدي الاختبار الاستدراكي إن حددته إدارة الامتحانات."),
    ("هل في الاختبار أسئلة تحريرية؟", "لا. أسئلة الاختبار المؤتمت كلها اختيار بإجابة واحدة صحيحة، تُصحَّح آلياً."),
    ("هل بعد الاختبار المؤتمت امتحان شفهي؟", "نعم. من ينجح في المؤتمت يختار موعده الشفهي أمام لجنة صفته في مركزه، من المواعيد التي تفتحها الإدارة بعد المؤتمت، ويستطيع تغييره قبل وقته. ولا يتأهل إلا بنجاحه فيهما معاً."),
    ("كيف تُحسب النتيجة؟", "تنجح باجتياز كل قسم من أقسام اختبارك بالنسبة المطلوبة فيه، كما تضبطها إدارة الامتحانات لكل اختبار (في هذه النسخة 50% لكل قسم). لا علامة إجمالية تُجمع ولا أوزان، ولا تُحتسب النتيجة قبل أن يؤكد المشرف تسليمك."),
    ("ما رمز المشرف السري؟", "رمز يضبطه مشرف القاعة لنفسه في لوحته، ويكتبه على جهازك بعد أن تسلّم ليؤكد أن من سلّم هو أنت. لا تعرفه ولا تحتاج إليه: ارفع يدك وانتظره في مقعدك."),
    ("كيف أصير رئيس تكتل؟", "لا يُتقدَّم لها ولا انتخاب. تمنح الإدارة صفة «رئيس تكتل»: صفةً أساسية لمن ثبّتته فيها، أو موسميةً لموسم واحد بسببها (كالزيادة العددية). ومن يحملها يحضر إلى المكتب في مدة تشكيل التكتلات مع رؤساء المجموعات وكادره، فيُشكَّل تكتله هناك."),
    ("هل أختار اسم مجموعتي وسعتها؟", "الاسم نعم: تخبر به موظف المكتب، باسم لا تحمله مجموعة أخرى، وبه تُعرف في المنصة كلها. والسعة لا: عدد حجاجها ومقاعد فريقها من فئتك في مستوى التكتل الذي تدخله. وفريقها يحضر معك إلى المكتب، فيُجلسه الموظف في مقاعدها حين يشكّلها."),
    ("لماذا لا يُدخل الموظف شخصاً اخترته في تكتلي؟", "لأن لكل شخص مكاناً واحداً في الموسم: من أخذه تكتل آخر أو مقعد في مجموعة أخرى لا يظهر بين المؤهلين الحاضرين. أو لأنه ليس في فروع التكتل، أو لأن الإدارة أوقفت حسابه."),
    ("هل تصلني دعوة إلى تكتل؟", "لا. لا دعوات على المنصة: كل مكان في التكتل يُعطى في المكتب بحضور صاحبه، حين تُشكَّل مجموعته أو يُشكَّل التكتل، ويظهر في «ملفي» وفي «الإشعارات» فوراً."),
    ("أين أجد العقد الذي وقّعته في المكتب؟", "في «العقود» من القائمة الجانبية: عقد مجموعتك يراه من فيها وحدهم، وعقد التكتل يراه كل من فيه. اضغط العقد لفتحه، و«تنزيل» لحفظه."),
    ("متى تُفتح صفحة الميدان؟", "بعد أن تدخل مجموعتك تكتلاً، للمنسق التقني في مجموعاته ولرئيس المجموعة ومعاونه في مجموعتهما، ويراها رئيس التكتل ومعاونه ومحاسبه للاطلاع. ولا ميدان للموجّه والموجّهة: عملهما الدروس والنشاطات الدينية."),
    ("متى أسجّل المنسك في «أداء المناسك»؟", "بعد أدائه، لا قبله: تؤدي المجموعة المنسك، ثم تسجّله بتاريخه وساعته ومكانه، ومن أدّاه، وسبب من لم يؤدّه. لا يُقبل وقت لم يأتِ بعد. وإن سجّلته خطأً فاحذفه من «سجل أداء المناسك» وسجّله من جديد."),
    ("لماذا أرى «للاطلاع فقط» في أعلى الصفحة؟", "لأنك رئيس التكتل أو معاونه أو محاسبه: تتابعون عمليات المجموعات كلها ولا تقومون بها. يقوم بها المنسق التقني في مجموعاته، ورئيس المجموعة ومعاونه في مجموعتهما، عدا التأشيرات والقوائم والطيران فهي للمنسق وحده."),
    ("من يضع الحجاج على حافلات المناسك؟", "المنسق التقني، من «القوائم»، على الحافلات التي يسندها فريق المواصلات في إدارة الحج والعمرة إلى التكتل لكل قائمة. وإن لم تتسع لحجاج مجموعاته طلب حافلة إضافية. ويرى رئيس المجموعة ومعاونه قوائم مجموعتهما، ورئيس التكتل ومعاونه ومحاسبه قوائم التكتل كله."),
    ("هل يضع المنسق التقني الحاج في مجموعة عندما يسجّل طلبه؟", "لا. التسجيل على الحج (وهو للمنسق التقني في أول الموسم، وتمنحه الإدارة لغيره إن شاءت) لا يضع أحداً في مجموعة. يتفق الحاج المقبول مع مجموعة ويوقّع عقده معها في المكتب، فيلحقه موظف المكتب بها."),
    ("لماذا ليس في فريق مجموعتي منسق تقني؟", "لأن المنسق التقني للتكتل لا للمجموعة. لكل تكتل منسقون بعدد مجموع فئات مجموعاته، ويوزّعهم رئيس التكتل على المجموعات حين يُشكَّل في المكتب، كلٌّ ضمن حدّه من الوحدات."),
    ("أريد تغيير أحد في تكتلي بعد إنشائه", "التعديل لا يكون في «إدارة التكتل»: تراجع المكتب، فيعدّله موظف إدارة الإداريين بحضورك تعديلاً استثنائياً بسبب يُكتب في سجل التكتل وفي ملف من مسّه."),
    ("كيف أراسل الإدارة؟", "من «المراسلات» في قائمتك: رسالة بموضوعها ونوعها ومرفقها. يصلك الرد في سياق الرسالة وفي الإشعارات، وتردّ فيه ما دامت مفتوحة."),
    ("ما درجات الموجّهين؟", "الموجّه الديني والموجّهة الدينية ثلاث درجات (أ، ب، ج)، تحددها الإدارة صفةً. الدرجة «أ» تمنح التكتل «شارة التميّز في التوجيه الديني»، ويُحتسب عمر صاحبها في متوسط أعمار التكتل 40، والدرجة «ب» 45 (والموجّهة «ب» 48). وكل الدرجات تؤدي اختبار الموجّه الديني."),
    ("عدّلت برنامج تكتلي ولا يظهر للحجاج", "التعديل ينتظر اعتماد الإدارة. يظهر للحجاج بعد الاعتماد فقط، وإن أُعيد تظهر لك أسبابه."),
]

